#### Phase 1: Test Framework Setup

1. **Create Extension Test Host**:
   ```csharp
   public class ExtensionTestHost : IDisposable
   {
       private readonly WebApplicationFactory<Program> _factory;
       private readonly IServiceProvider _services;

       public ExtensionTestHost(string productVersion)
       {
           _factory = new WebApplicationFactory<Program>()
               .WithWebHostBuilder(builder =>
               {
                   builder.ConfigureAppConfiguration(config =>
                   {
                       config.AddInMemoryCollection(new[]
                       {
                           new KeyValuePair<string, string>("ProductVersion", productVersion)
                       });
                   });
               });
           _services = _factory.Services;
       }

       public TExtension LoadExtension<TExtension>(string extensionName)
           where TExtension : class
       {
           var loader = _services.GetRequiredService<IExtensionLoader>();
           return loader.Load<TExtension>(extensionName);
       }
   }
   ```

2. **Configure Test Infrastructure**:
   ```yaml
