   public class TexasClaimProcessorTests : ExtensionIntegrationTestBase
   {
       [Fact]
       public async Task ProcessClaim_WithValidData_Succeeds()
       {
           // Arrange
           var processor = TestHost.LoadExtension<IClaimProcessor>("TexasClaimProcessor");
           var claim = TestDataRepository.CreateValidTexasClaim();
           var context = new ProcessingContext { TenantId = "Texas-Medicaid" };

           // Act
           var result = await processor.ProcessAsync(claim, context, CancellationToken.None);

           // Assert
           Assert.True(result.Success);
           Assert.NotNull(result.ProcessedClaim);
       }

       [Theory]
       [InlineData("2.0.0")]
       [InlineData("2.1.0")]
       [InlineData("2.2.0")]
       public async Task ProcessClaim_CompatibleAcrossVersions(string version)
       {
           // Test extension against multiple product versions
           using var host = new ExtensionTestHost(version);
           var processor = host.LoadExtension<IClaimProcessor>("TexasClaimProcessor");
           var claim = TestDataRepository.CreateValidTexasClaim();

           var result = await processor.ProcessAsync(claim, new ProcessingContext(), CancellationToken.None);

           Assert.True(result.Success);
       }
