9. **Create Compatibility Matrix Generator**:
   ```csharp
   public class CompatibilityMatrixGenerator
   {
       private readonly ITestResultRepository _results;

       public async Task<CompatibilityMatrix> GenerateMatrixAsync()
       {
           var extensions = await GetAllExtensions();
           var versions = new[] { "2.0.0", "2.1.0", "2.2.0" };
           var matrix = new CompatibilityMatrix();

           foreach (var extension in extensions)
           {
               var row = new CompatibilityRow { Extension = extension };

               foreach (var version in versions)
               {
                   var results = await _results.GetTestResultsAsync(extension, version);
                   row.Results[version] = new CompatibilityResult
                   {
                       Status = results.AllPassed ? Status.Pass : Status.Fail,
                       TestCount = results.Total,
                       FailureCount = results.Failed,
                       ExecutionTime = results.Duration
                   };
               }

               matrix.Rows.Add(row);
           }

           return matrix;
       }
   }
   ```

