### Real-World Example 2: New Extension Validation

**Context**: New California provider extension must be validated against supported product versions (2.0, 2.1, 2.2) before deployment.

**Implementation**:

```csharp
public class NewExtensionValidator
{
    private readonly string[] _supportedVersions = { "2.0.0", "2.1.0", "2.2.0" };

    public async Task<NewExtensionValidationReport> ValidateNewExtensionAsync(
        string extensionPath)
    {
        var report = new NewExtensionValidationReport();

        // Load extension package
        var extension = await LoadExtensionPackageAsync(extensionPath);
        report.ExtensionName = extension.Name;
        report.ExtensionVersion = extension.Version;

        Console.WriteLine($"Validating {extension.Name} v{extension.Version}...");

        // Test against each supported version
        foreach (var version in _supportedVersions)
        {
            Console.WriteLine($"  Testing against product {version}...");
            var result = await TestExtensionAgainstVersionAsync(extension, version);
            report.VersionResults[version] = result;

            if (result.AllTestsPassed)
                Console.WriteLine($"    ✅ All tests passed");
            else
                Console.WriteLine($"    ❌ {result.FailedTests.Count} test(s) failed");
        }

        // Determine overall approval status
        report.Approved = report.VersionResults.Values.All(r => r.AllTestsPassed);
        report.MinimumSupportedVersion = report.VersionResults
            .Where(kvp => kvp.Value.AllTestsPassed)
            .Select(kvp => kvp.Key)
            .OrderBy(v => v)
            .FirstOrDefault();

        return report;
    }

    private async Task<VersionTestResult> TestExtensionAgainstVersionAsync(
        ExtensionPackage extension, string productVersion)
    {
        var result = new VersionTestResult { ProductVersion = productVersion };

        using var testHost = new ExtensionTestHost(productVersion);

        // Load extension
        try
        {
            await testHost.LoadExtensionPackageAsync(extension);
            result.LoadSucceeded = true;
        }
        catch (Exception ex)
        {
            result.LoadSucceeded = false;
            result.FailedTests.Add($"Load failed: {ex.Message}");
            return result;
        }

        // Run test suite
        var testResults = await testHost.RunExtensionTestsAsync(extension.Name);
        result.TotalTests = testResults.Total;
        result.PassedTests = testResults.Passed;
        result.FailedTests = testResults.Failures.Select(f => f.Message).ToList();
        result.ExecutionTime = testResults.Duration;

        // Performance benchmarks
        var perfResults = await testHost.RunPerformanceBenchmarksAsync(extension.Name);
        result.PerformanceMetrics = perfResults.Metrics;
        result.MeetsPerformanceTargets = perfResults.AllTargetsMet;

        result.AllTestsPassed = result.LoadSucceeded &&
                               testResults.Passed == testResults.Total &&
                               perfResults.AllTargetsMet;

        return result;
    }
}
```

